function localizeMenuEntity<T extends LocalizedMenuEntity>(entity: T, language: Language, entityType: "category" | "item" | "addon", runtimeTranslations?: Map<string, RuntimeMenuTranslation>): T { const approved = (entry: { language: string; status?: string }) => !entry.status || ["approved", "auto", "auto-approved"].includes(entry.status); try { const runtime = entity.id ? runtimeTranslations?.get(`${entityType}:${entity.id}:${language}`) : null; const translations = entity.translationsJson ? JSON.parse(entity.translationsJson) as Array<{ language: string; name: string; description?: string | null; status?: string }> : []; const match = runtime ?? translations.find((entry) => entry.language === language && approved(entry)) ?? (entity.id ? readMenuTranslation(entityType, entity.id, language, entity.name, entity.description) : null); if (match && "name" in match && match.name) return { ...entity, name: match.name, description: match.description ?? entity.description }; } catch { /* malformed optional translations never block menu rendering */ } if (language !== "ar") return { ...entity, name: language === "fr" ? "Traduction en attente" : "Translation pending", description: null }; return entity; }

type CheckoutChannel = "dineIn" | "takeaway" | "delivery" | "reservation" | "hotel";
export function validateCheckoutDetails(input: { channel: CheckoutChannel; tableName?: string; pickupPoint?: string; pickupPointRequired?: boolean; deliveryAddress?: string; deliveryLatitude?: number; deliveryLongitude?: number; reservationDate?: string; reservationEventType?: string; hotelId?: number | null; hotelRoomId?: number | null; hotelName?: string; hotelRoom?: string; hotelFloor?: string }): string | null {
  const required = (value: string | undefined, message: string) => value?.trim() ? null : message;
  if (input.channel === "dineIn") return required(input.tableName, "رقم الطاولة مطلوب للطلب داخل المطعم");
  if (input.channel === "takeaway") return input.pickupPointRequired ? required(input.pickupPoint, "نقطة الاستلام مطلوبة للطلب السفري") : null;
  if (input.channel === "delivery") { return required(input.deliveryAddress, "عنوان التوصيل مطلوب") ?? (input.deliveryLatitude === undefined || input.deliveryLongitude === undefined ? "حدد موقع التوصيل على الخريطة" : null); }
  if (input.channel === "reservation") return required(input.reservationDate, "موعد الحجز مطلوب") ?? required(input.reservationEventType, "نوع المناسبة مطلوب");
  return input.hotelId ? (input.hotelRoomId ? null : "اختر رقم الغرفة من الغرف المتزامنة") : "اختر الفندق المرتبط بالمطعم";
}
