              {detailSizeOptions.length > 0 && <section className="mt-5"><p className="mb-2 text-sm font-black text-slate-900">{detailCopy.sizes}</p><div className="grid gap-2 sm:grid-cols-2">{detailSizeOptions.map((size) => <label key={size.id} className={`flex cursor-pointer items-center justify-between gap-3 rounded-xl border p-3 text-sm transition ${selectedDetailSize?.id === size.id ? "border-orange-300 bg-orange-50" : "border-slate-100 bg-slate-50"}`}><span className="flex min-w-0 items-center gap-2"><input type="radio" name="product-detail-size" value={size.id} checked={selectedDetailSize?.id === size.id} onChange={() => setDetailSizeId(size.id)} className="h-4 w-4 accent-orange-500" /><span className="truncate font-bold text-slate-700">{size.name}</span></span>{Number(size.price ?? 0) > 0 && <span className="shrink-0 text-xs font-black text-orange-700">+{formatPrice(Number(size.price))}</span>}</label>)}</div></section>}
              {detailAddons.length > 0 && <section className="mt-5"><p className="mb-2 text-sm font-black text-slate-900">{detailCopy.addons}</p><div className="space-y-2">{detailAddons.map((addon) => { const checked = detailAddonIds.includes(addon.id); return <label key={addon.id} className={`flex cursor-pointer items-center justify-between gap-3 rounded-xl border p-3 text-sm transition ${checked ? "border-orange-300 bg-orange-50" : "border-slate-100 bg-slate-50"}`}><span className="flex min-w-0 items-center gap-2"><input type="checkbox" checked={checked} onChange={() => setDetailAddonIds((current) => checked ? current.filter((id) => id !== addon.id) : [...current, addon.id])} className="h-4 w-4 rounded accent-orange-500" /><span className="truncate font-bold text-slate-700">{addon.name}</span></span><span className="shrink-0 text-xs font-black text-orange-700">+{formatPrice(Number(addon.price))}</span></label>; })}</div></section>}
              {detailData.reviews?.length ? <section className="mt-5 rounded-2xl bg-slate-50 p-4"><div className="flex items-center justify-between gap-3"><p className="text-sm font-black text-slate-900">{detailCopy.reviews}</p><span className="text-xs font-black text-orange-700">★ {detailReviewAverage.toFixed(1)} · {detailData.reviews.length}</span></div><div className="mt-3 space-y-2">{detailData.reviews.slice(0, 3).map((review, index) => <p key={String(review.id ?? index)} className="rounded-xl bg-white p-3 text-xs leading-5 text-slate-600">{review.text || ""}{review.author ? <span className="mt-1 block text-[10px] font-bold text-slate-400">{review.author}</span> : null}</p>)}</div></section> : null}
